import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(7,1,{
 title:'Diffusion：为什么训练去噪能用于生成',summary:'先认识加噪程度与去噪目标，再把一次训练和多步采样拆成两条独立流程。',prerequisites:['w3-l2','w6-l3'],
 terms:[T('Diffusion 扩散模型','通过逐步加噪构造学习问题，再学习相应反向生成过程的一类模型。','常从随机噪声出发，多次调用去噪网络得到样本。'),T('噪声时间 t','描述样本处于哪一种噪声程度的条件。','它不是训练已经更新了多少步。'),T('去噪目标','网络要预测的对象，可能是噪声、干净数据或其他参数化。','经典噪声预测例子让网络估计加进图片的噪声。'),T('采样器 sampler','使用网络预测、时间表和数值更新规则产生样本的程序。','固定权重后，更换采样步数仍可能改变结果。')],
 sections:[P('第 1 步：人为构造一张带噪图片','设干净样本 x0 已知，随机采一个噪声 epsilon，再根据时间 t 混合得到 xt。一种常见形式是 xt=sqrt(alpha_bar_t)*x0+sqrt(1−alpha_bar_t)*epsilon。系数来自预先定义的噪声日程。','这不是模型自己猜出的未来数据，而是训练者从已知样本构造的监督任务。每次可以随机选不同 t，因此网络需要接收 t 才知道当前噪声程度。'),P('第 2 步：定义网络要猜什么','在噪声预测形式中，网络输入 xt、t 和可选条件，输出 epsilon_hat，与已知 epsilon 比较均方误差。其他参数化会改变目标公式，不能把不同训练器的输出都当成噪声。','每个训练更新通常只需要抽取一些 t 来计算目标，不是每次都从头到尾完整去噪一张图。训练更新次数与噪声过程时间是两条不同坐标。'),P('第 3 步：生成时干净答案并不存在','生成从随机噪声开始，在多个噪声时间上调用训练后的网络，由采样器逐步更新状态。网络预测只是每一步更新所需的信息，不能直接等同于最终图片。','采样步数、随机种子和更新算法影响生成速度与误差。减少步数不一定改变网络参数，却可能让近似过程更粗糙。比较训练改进时要固定这些推理设置。'),P('第 4 步：区分扩散训练与普通输入加噪','给一个 AR 预测器的输入加噪，可能只是为了增强鲁棒性。如果它训练时仍直接预测下一帧，推理时也不执行扩散反向过程，不能仅凭“用了噪声”就叫 DDPM。','DDPM 是一类具体扩散模型方法；UNet、Transformer 则是可承载预测计算的网络结构。看系统时同时记录结构、目标和采样过程。')],
 worked:{title:'一个标量的带噪构造',steps:['取 x0=2，epsilon=−1，alpha_bar=0.64。','sqrt(0.64)=0.8，sqrt(0.36)=0.6。','xt=0.8×2+0.6×(−1)=1。','若网络预测噪声为 −0.5，本例噪声 MSE 为 (−0.5+1)²=0.25。'],takeaway:'先能写清输入和目标，才算看懂一种去噪训练形式。'},
 example:{code:'import math\nx0, noise, alpha_bar = 2.0, -1.0, 0.64\nxt = math.sqrt(alpha_bar)*x0 + math.sqrt(1-alpha_bar)*noise\npredicted_noise = -0.5\nprint("noisy input", round(xt, 4))\nprint("noise loss", (predicted_noise-noise)**2)',output:'noisy input 1.0\nnoise loss 0.25',explanation:'这段代码只构造一个训练样本及其误差，没有训练网络，也没有实现完整反向采样。'},
 checks:[Q('噪声时间 t=500 是否表示模型训练了 500 步？','时间 t 描述样本还是优化器进度？','不是。它描述噪声状态；一次参数更新可使用任意抽到的噪声时间。',1),Q('给 AR 输入加高斯噪声，是否一定变成扩散模型？','查看目标和推理更新过程。','不一定。可能只是数据增强，仍需依据完整训练与采样流程分类。',3)],
 practice:{title:'把训练与采样画成两条流程',steps:[A('改变 alpha_bar，计算不同噪声程度的 xt。','能说明干净样本和噪声的系数如何变化。','不要把本例的线性标量当作真实图像效果。'),A('画训练路径：真实样本、噪声、xt、网络、监督损失。','每个目标都能追溯到已知量。','网络输出类型必须写清。'),A('画生成路径：随机噪声、重复网络调用、采样器更新。','能指出生成时没有真实 x0 可供直接查询。','把优化器 step 与采样器 step 写在不同地方。')]},sources:[S.ddpm,S.mit]
}),
L(7,2,{
 title:'Flow Matching、DiT 和视觉 AR：三个名字分别说什么',summary:'用一条直线路径学习速度目标，再区分网络结构、学习目标和生成顺序。',prerequisites:['w7-l1','w2-l3'],
 terms:[T('Flow Matching 流匹配','构造概率路径的速度监督，训练网络预测速度场，并通过积分产生样本的方法。','简单直线路径的单对样本速度目标是终点减起点。'),T('速度场 vector field','为当前位置、时间和条件给出移动方向与速度的函数。','生成时并不知道目标终点，需要调用学到的速度网络。'),T('数值积分','用有限小步近似沿速度场移动的计算。','Euler 更新是 x_next=x+dt*v(x,t)。'),T('DiT','把 Transformer 用作扩散类生成建模主干的一类架构。','结构名字不能单独确定采用噪声预测还是流匹配目标。'),T('视觉 AR','把视觉内容按某种顺序组织为序列，用已有部分预测下一部分。','下一项可以是离散图像编号或连续视觉表示。')],
 sections:[P('第 1 步：从已知起点与终点构造路径','训练时可以取噪声起点 x0 和数据终点 x1，设 xt=(1−t)*x0+t*x1。对此直线路径，速度是 x1−x0。网络学习从 xt、t 和条件预测对应速度信息。','不同端点配对和路径设计会影响学习问题。不要把这个最简单公式误认为所有 Flow Matching 方法都使用同一耦合或同一采样器。'),P('第 2 步：生成时不能偷用训练终点','生成只给一个新的噪声起点，并没有 x1。网络必须根据当前位置与时间预测速度，再由数值积分逐步移动。网页里的路径插值演示已知两端，只解释训练路径，不等于训练出了生成器。','Euler 方法每步用当前速度走 dt。步数少时近似误差可能较大；步数增加也不能修复一个学错的速度场。网络误差与求解误差应分别理解。'),P('第 3 步：把结构和目标放到不同栏','DiT 告诉你主干使用 Transformer 处理生成建模中的表示。Flow Matching 告诉你怎样构造速度监督。一个系统可以同时使用二者，就像第 5 周的 SFT 与 LoRA 分属不同维度。','UNet 是另一类常见的多尺度主干，带编码、解码和跳连等结构。比较不同主干必须尽量控制参数、预算、数据和目标，而不是只比较名字。'),P('第 4 步：视觉 AR 的“下一项”由序列定义','把图像切成离散码本编号，AR 可以预测下一个编号；把视频帧编码成连续 latent，也可以按历史预测下一帧或下一块。目标和输出头要与表示类型一致。','一个 Decoder-only 世界模型可能自回归预测未来视觉表示，但这还没说明是否动作条件、是否能解码、是否能用于规划。第 8 周会把这些接口补全。')],
 worked:{title:'训练路径与生成积分要分清',steps:['训练配对：x0=−1、x1=3，t=0.25，则 xt=0，速度目标为 4。','若已知常速度 4，Euler 步长 0.25，每步增加 1。','走四步从 −1 到 3，这是已知速度的数值演示。','实际生成时速度来自网络，不能直接使用未知 x1−x0。'],takeaway:'路径公式提供监督；学到的速度场加求解器才组成生成过程。'},
 example:{code:'x0, x1, t = -1.0, 3.0, 0.25\nxt = (1-t)*x0+t*x1\nvelocity = x1-x0\nprint("training point", xt, "target velocity", velocity)\nx = x0\nfor _ in range(4):\n    x += 0.25*velocity\nprint("known-velocity endpoint", x)',output:'training point 0.0 target velocity 4.0\nknown-velocity endpoint 3.0',explanation:'速度在这个玩具例子中是已知常数。它用于理解积分，不是训练后的随机样本生成。'},
 checks:[Q('网页能把噪声点移动到已知终点，是否证明生成模型已经学会？','路径是否使用了目标终点？','不能。已知配对插值与从未知终点生成是不同任务。',1),Q('“DiT + Flow Matching”是否冲突？','各自描述结构还是学习目标？','不冲突，前者主要描述网络主干，后者描述速度监督与路径学习方式。',2)],
 practice:{title:'给生成系统做三栏说明',steps:[A('使用 Flow Matching 交互实验，观察 t 从 0 到 1。','能明确说这是给定路径，不是采样质量。','不要把界面平滑运动当成模型训练成果。'),A('分别填写主干、目标、采样器三栏。','例如 Transformer、速度预测、某种积分方法。','每一栏都需要实现或配置证据。'),A('用代码改变 Euler 步长，并保持总时间为 1。','常速度例子终点相同；实际非恒定速度才会表现求解误差。','这个例子无法据此证明“真实模型步数无影响”。')]},links:[{label:'Flow Matching 路径实验',href:'#/labs/flow'}],sources:[S.flow,S.dit,S.mit]
}),
L(7,3,{
 title:'图像质量怎样评价：清晰、匹配、偏好不是同一个分数',summary:'从四项不同评价需求出发，认识 PSNR、FID、图文匹配与奖励优化的边界。',prerequisites:['w4-l3','w5-l3','w7-l2'],
 terms:[T('PSNR 峰值信噪比','根据像素均方误差和像素范围计算的重建类指标。','需要可对齐的参考图像；高分不等于所有语义正确。'),T('FID','比较两组图像在特定特征空间中分布统计差异的指标。','它是集合比较，不用于给单张图的提示遵循直接打分。'),T('ImageReward','学习人类图像偏好的奖励模型研究与系统之一。','它提供一种评价信号，不等于真实偏好的无偏测量。'),T('CFG 无分类器引导','在条件与无条件预测之间进行引导组合的一类采样方式。','引导强度是推理设置，可能影响提示遵循与多样性的权衡。')],
 sections:[P('第 1 步：先把“好看”拆成可检查的问题','重建是否接近参考？提示要求的物体、数量和关系是否正确？视觉是否自然？同一提示能否产生多样且合理的结果？这四项需要不同证据。','不要先挑一个流行指标再宣称它代表全部质量。先写使用场景，再决定自动指标、人工盲评和失败类型。'),P('第 2 步：理解像素与分布指标的限制','PSNR 来自像素误差，计算前必须统一分辨率、范围与对齐。整体稍微平移可能产生较大像素误差，而语义仍相似；模糊平均图有时也会在某些像素指标上占便宜。','FID 使用一组生成图与一组参考图的特征统计，受样本量、特征提取和预处理影响。不能用一张图片的 FID 判断是否有“恰好三只猫”。'),P('第 3 步：固定生成条件再比较','同一提示集、随机种子集合、分辨率、采样步数与 CFG 强度下进行对比。盲评时隐藏方法名并打乱左右顺序，允许平局，记录评审规则。','固定种子便于配对比较，但一个种子不足以代表输出分布。报告所有预先选定提示的总体结果，而不是只展示最佳案例。'),P('第 4 步：把奖励当成可被检查的代理目标','用 ImageReward 或类似评分器选样，与用奖励训练生成器是不同流程。无论哪一种，都需要独立人工或任务评价来检查评分器偏差。','如果奖励分数上涨，但正确物体数量下降，报告应并列呈现冲突。优先排查模型是否利用了评分器喜欢的风格、饱和度或文字模式，而不是隐藏不利指标。')],
 worked:{title:'一次小型人工对比如何计数',steps:['固定 5 个提示的配对输出，盲评结果为 A 胜 3、B 胜 1、平局 1。','可以报告三类计数，避免用含糊的“胜率”掩盖平局处理。','若按平局各半计分，A 的分数为 (3+0.5)/5=70%。','样本很少，只能作为初步观察，不足以证明稳定优势。'],takeaway:'指标的计算规则、样本范围和不确定性必须一起报告。'},
 example:{code:'results = ["A", "tie", "B", "A", "A"]\na, b, ties = results.count("A"), results.count("B"), results.count("tie")\nprint("counts", a, b, ties)\nprint("A half-tie score", (a+0.5*ties)/len(results))',output:'counts 3 1 1\nA half-tie score 0.7',explanation:'平局各半是一种明确的计分约定，不是唯一合法方式；报告时必须说明。'},
 checks:[Q('单张图能否通过 FID 直接证明提示遵循正确？','FID 的输入单位是什么？','不能。它比较图像集合的特征分布，不直接检验单图中的数量、关系和指令条件。',1),Q('奖励上涨而人工偏好下降时，能只报告奖励吗？','想想最终使用目标是什么。','不应如此。需要呈现冲突并分析评分偏差、奖励投机和评测范围。',3)],
 practice:{title:'写一份公平的图像对比协议',steps:[A('设计 10 个提示，覆盖物体、数量、空间关系和风格。','每类有明确判据，而不是只写“更漂亮”。','不要根据已生成的结果再挑容易赢的提示。'),A('记录种子、分辨率、步数和引导强度。','两种方法的推理预算和设置可复查。','配置不同必须在结论里说明。'),A('设计盲评表，保留平局和失败原因。','输出逐例记录和总体计数。','本课提供协议与计算练习，不要求购买生图服务。')]},sources:[S.reward,S.ddpo,S.ddpm]
})];
